create extension if not exists pgtap with schema extensions;
begin;
set local role postgres;
set local search_path = extensions, public, pg_catalog;
select plan(9);
insert into auth.users(id,email) values ('53460000-0000-4000-8000-000000000001','race-owner@example.invalid');
insert into public.events(id,owner_id,event_type) values ('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','wedding');
select ok(public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','53460000-0000-4000-8000-000000000010/orphan.pdf'),'orphan path eligible');
insert into private.event_document_upload_reservations(id,event_id,actor_id,idempotency_key,object_path,original_name,mime_type,file_size,category,expires_at) values ('53460000-0000-4000-8000-000000000020','53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001',gen_random_uuid(),'53460000-0000-4000-8000-000000000010/upload.pdf','upload.pdf','application/pdf',1,'generic',now()+interval '15 minutes');
select is(public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','53460000-0000-4000-8000-000000000010/upload.pdf'),false,'active upload cannot be swept');
update private.event_document_upload_reservations set status='finalized' where id='53460000-0000-4000-8000-000000000020';
select is(public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','53460000-0000-4000-8000-000000000010/upload.pdf'),false,'newly finalized upload cannot be swept');
update private.event_document_upload_reservations set status='cleanup_pending' where id='53460000-0000-4000-8000-000000000020';
select is(public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','53460000-0000-4000-8000-000000000010/upload.pdf'),false,'pending upload uses claimed cleanup protocol');
update private.event_document_upload_reservations set status='expired' where id='53460000-0000-4000-8000-000000000020';
insert into public.event_documents(event_id,created_by,original_name,object_path,mime_type,file_size) values ('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','upload.pdf','53460000-0000-4000-8000-000000000010/upload.pdf','application/pdf',1);
select is(public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','53460000-0000-4000-8000-000000000010/upload.pdf'),false,'metadata protects path independently');
select throws_ok($q$select public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000001','other-event/file.pdf')$q$,'42501','DOCUMENT_RESERVATION_MISMATCH','cross-event path denied');
select ok(not has_function_privilege('authenticated','public.event_document_path_is_untracked(uuid,uuid,text)','EXECUTE'),'browser cannot invoke cleanup guard');
select ok(has_function_privilege('service_role','public.event_document_path_is_untracked(uuid,uuid,text)','EXECUTE'),'service can invoke cleanup guard');
select throws_ok($q$select public.event_document_path_is_untracked('53460000-0000-4000-8000-000000000010','53460000-0000-4000-8000-000000000099','53460000-0000-4000-8000-000000000010/orphan.pdf')$q$,'42501','EVENT_ACCESS_DENIED','foreign actor denied');
select * from finish();
rollback;
